class Expr:
  pass

class Ident(Expr):
  def __init__(self, ident: str):
    self.ident = ident

  def __str__(self) -> str:
    return self.ident

class Minus(Expr):
  def __init__(self, arg: Expr):
    self.arg = arg

  def __str__(self) -> str:
    return '-\n' + indent(str(self.arg), '  ')

class Times(Expr):
  def __init__(self, left: Expr, right: Expr):
    self.left, self.right = left, right

