def typ():
  if SC.sym == IDENT:
    ident = SC.val
    x = find(ident)
    if type(x) == Type:
      x = Type(x.val)
      getSym()
    else:
      mark('type identifier expected')
  elif SC.sym == LBRAK:
    getSym()
    x = expression()
    if SC.sym == DOTDOT:
      getSym()
    else:
      mark("'..' expected")
    y = expression()
    if SC.sym == RBRAK:
      getSym()
    else:
      mark("']' expected")
    if SC.sym == RARROW:
      getSym()
    else:
      mark("'→' expected")
    z = typ().val
    if type(x) != Const or x.val < 0:
      mark('bad lower bound')
    elif type(y) != Const or y.val < x.val:
      mark('bad upper bound')
    else:
      x = Type(CG.genArray(Array(z, x.val, y.val - x.val + 1)))
  elif SC.sym == LPAREN:
    getSym()
    openScope()
    typedIds()
    if SC.sym == RPAREN:
      getSym()
    else:
      mark("')' expected")
    r = topScope()
    closeScope()
    x = Type(CG.genRec(Record(r)))
  elif SC.sym == SET:
    getSym()
    if SC.sym == LBRAK:
      getSym()
    else:
      mark("'[' expected")
    x = expression()
    if SC.sym == DOTDOT:
      getSym()
    else:
      mark("'..' expected")
    y = expression()
    if SC.sym == RBRAK:
      getSym()
    else:
      mark("']' expected")
    if type(x) != Const:
      mark('bad lower bound')
    elif type(y) != Const or y.val < x.val:
      mark('bad upper bound')
    else:
      x = Type(CG.genSet(Set(x.val, y.val - x.val + 1)))
  else:
    mark('type expected')
  return x
